class Locker {
  #code;

  constructor(code) {
    this._owner = "Ada";
    this.#code = code;
  }

  open(code) {
    return code === this.#code;
  }
}

const locker = new Locker(42);

locker._owner = "Leo";
locker["#code"] = 0;

console.log(locker.open(0));
console.log(locker.open(42));
console.log(Object.keys(locker).join(","));
console.log(JSON.stringify(locker));
